namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Services")]
    [TestClass]
    public class RJIT_CR_S_00002 : ServiceTestBase
    {
        [TestMethod]
        public void Each_Service_Should_Register_Its_Dependencies_Too()
        {
            var missingServiceRegistrations = (from service in FindMissingDependencyRegistrations()
                                               select new
                                               {
                                                   Error = $@"
Your service:       {service.Service.Name} does not call all registrations for each dependency in the constructor.
                    Keep in mind who ever use your service will only call one registration method for your service.
                    Each service is responsible to register its dependencies too.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullQualifiedName:  {service.Service.FullQualifiedName}.{service.Service.Name}'
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Registration:

{service.Registration.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Should Be:             

{service.Service.BuildServiceRegistration(Classes)}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                               }).ToImmutableList();

            Assert.IsTrue(missingServiceRegistrations.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_S_00002

Missing dependencies in service registrations. Findings {missingServiceRegistrations.Count}': {Environment.NewLine}{missingServiceRegistrations.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");


            IEnumerable<(Class Service, Class Registration)> FindMissingDependencyRegistrations()
            {
                foreach (var service in Services)
                {
                    if (service.Registration.IsNull())
                    {
                        continue;
                    }
                    
                    foreach (var registrationMethod in service.Registration.Methods)
                    {
                        foreach (var parameter in service.Class.Parameters)
                        {
                            // Injection of multiple services
                            if (parameter.Type.StartsWith("IEnumerable<", StringComparison.OrdinalIgnoreCase))
                            {
                                var type = GlobalRegex.GetGenericTypeRegex().Match(parameter.Type).Groups[1].Value;
                                var allTypes = Classes.Where(c => c.BaseTypes.Any(b => b.TypeName == type)).ToImmutableList();
                                var typesRegistrations = allTypes.Select(value => $"Add{value.Name}").ToImmutableList();
                                if(typesRegistrations.All(reg => registrationMethod.MethodBody.Contains(reg)))
                                {
                                    continue;
                                }
                                
                                yield return (service.Class, service.Registration);
                            }
                            
                            var registration = parameter.Type.Take(2).All(c => char.IsUpper(c)) && parameter.Type[0] == 'I' ? parameter.Type.Substring(1) : parameter.Type;
                            var expectedRegistration = $"Add{registration}";
                            if (registrationMethod.MethodBody.Contains(registration))
                            {
                                continue;
                            }
                            
                            yield return (service.Class, service.Registration);
                            yield break;
                        }   
                    }
                }
            }
        }
    }
